"""Auditor-style replay: every possible rolling window must hold <= limit allowed calls,
and retry_after must be exactly sufficient."""
import random, sys, importlib, math
sys.path.insert(0, "/tmp"); sys.path.insert(0, ".")
from ratelimit.limiter import RateLimiter as New
from audit_old import RateLimiter as Old

def worst_window(times, window):
    # max number of allowed calls in any half-open window (t-window, t]
    times=sorted(times); best=0; j=0
    for i,t in enumerate(times):
        while times[j] <= t-window: j+=1
        best=max(best, i-j+1)
    return best

def replay(cls, limit, window, seed, n=3000):
    rng=random.Random(seed); rl=cls(limit, window); now=0.0; allowed=[]
    for _ in range(n):
        now += rng.choice([0.0, rng.random()*0.3, rng.random()*window*1.5])
        if rl.allow("k", now): allowed.append(now)
    return worst_window(allowed, window)

viol_old=viol_new=0
for seed in range(300):
    limit=random.Random(seed).randint(1,10); window=random.Random(seed+1).uniform(0.5,20)
    if replay(Old,limit,window,seed)>limit: viol_old+=1
    if replay(New,limit,window,seed)>limit: viol_new+=1
print("rolling-window violations (300 random replays): old token bucket =", viol_old, "| new sliding log =", viol_new)

# retry_after: waiting exactly that long always suffices, and never over-waits.
bad=0; checks=0
for seed in range(2000):
    rng=random.Random(seed); limit=rng.randint(1,6); window=rng.uniform(0.1,50)
    rl=New(limit,window); now=rng.uniform(0,1e6)
    if rng.random()<0.3: rl.set_limit("k", rng.randint(1,6))
    for _ in range(40):
        now += rng.random()*window*0.4
        if not rl.allow("k", now):
            w=rl.retry_after("k", now); checks+=1
            if w<=0 or not rl.allow("k", now+w): bad+=1
            # strictly less than the returned wait must still be denied (tight, not padded)
            elif w>1e-9:
                probe=New(limit,window)  # can't rewind; check tightness by remaining() instead
    if rl.retry_after("k", now)!=0.0 and rl.remaining("k", now)>0: bad+=1
print("retry_after checks:", checks, "failures:", bad)
